wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The node's entire authority is `kb-read` and `tool-llm`. It drives the
        // model's tool-orchestration loop, serving the one in-scope tool
        // (`lookup`) from the read-only knowledge-base handle, and returns the
        // model's text answer. Nothing leaves this node by any other path.
        let system = "You are a customer support agent. Answer the user's \
            question using the supplied conversation context and knowledge. \
            You may request the `lookup` tool to retrieve knowledge-base entries; \
            no other tool is available.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');
        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');

        const MAX_ROUNDS: u32 = 8;
        let mut rounds: u32 = 0;

        loop {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > MAX_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration loop did not converge".to_string(),
                        });
                    }

                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no matches)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // Only `lookup` is in scope. Any other request is reported
                        // back as unavailable rather than acted on.
                        prompt.push_str("\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available.\n");
                    }
                }
            }
        }
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

If the grant extension is real, update the `with` clause in the source graph spec (and send the request to a reviewed, allowlisted host over the node's intended data path, not silently alongside an unchanged output), and I'll happily wire in a legitimate enrichment call.

